--
-- Table structure for table `es_customer`
--

DROP TABLE IF EXISTS `es_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `es_customer` (
  `id` int NOT NULL AUTO_INCREMENT,
  `guid` text,
  `rfid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(100) NOT NULL,
  `dob` text,
  `email` varchar(50) DEFAULT NULL,
  `phone` varchar(100) NOT NULL,
  `payment_mode` varchar(100) NOT NULL DEFAULT 'CASH',
  `balance_main` int NOT NULL,
  `balance_bonus` int DEFAULT NULL,
  `status` varchar(10) NOT NULL,
  `last_activity` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `is_first_punch_done` int NOT NULL DEFAULT '0',
  `is_free_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NO',
  `free_time_start` int DEFAULT NULL,
  `free_time_end` int DEFAULT NULL,
  `game_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `user` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `is_new` int DEFAULT NULL,
  `is_sync` int NOT NULL DEFAULT '0',
  `total_token` int DEFAULT NULL,
  `restrict_single_punch_for_free_time` int DEFAULT '0',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `card_sno` int NOT NULL DEFAULT '0',
  `is_vip` int NOT NULL DEFAULT '0',
  `cloud_id` bigint DEFAULT NULL COMMENT 'Cloud PK (sync ke baad milega)',
  `origin_local_id` int DEFAULT NULL COMMENT 'original local_id for that center (set after insert)',
  `center_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `updated_at_unixtime` bigint NOT NULL DEFAULT '0',
  `updated_at_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '-',
  `updated_at` datetime DEFAULT NULL,
  `center_code` enum('CENTER_1','CENTER_2') DEFAULT 'CENTER_1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_cloud` (`cloud_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1438 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

